import Foundation
import XCTest
@testable import GoonersPayKit

/// The app computes exactly what the platform computes: payments/mobile/conformance/vectors.json
/// is generated by the Go platform (cmd/conformance) and checked by the Kotlin core and the
/// JavaScript spec tools as well.
final class ConformanceTests: XCTestCase {
    static let mobile = URL(fileURLWithPath: #filePath).deletingLastPathComponent().deletingLastPathComponent()
        .deletingLastPathComponent().deletingLastPathComponent()

    struct Vectors: Decodable {
        struct Bip340: Decodable { var secret, pubkey, message, aux, signature: String }
        struct TestKey: Decodable { var role, secret, pubkey, npub, nsec: String }
        struct Signed: Decodable { var name: String; var aux: String; var serialization: String; var event: NostrEvent }
        struct Nip98: Decodable { var method, url, body, aux, authorizationHeader: String; var event: NostrEvent }
        struct Thumb: Decodable { var jwk: JWK; var thumbprint: String }
        struct List: Decodable { var aux: String; var event: NostrEvent }
        struct Card: Decodable { var key, ksn, nonce, plaintext, ciphertextBase64, format: String }
        struct Code: Decodable { var code: String; var dynamic: Bool; var amount: String?; var merchantName: String; var url: String?; var key: String? }
        struct Amount: Decodable { var centavos: Int64; var display: String }
        var bip340: [Bip340]
        var testKeys: [TestKey]
        var events: [Signed]
        var nip98: Nip98
        var jwkThumbprint: Thumb
        var deviceList: List
        var devCard: Card
        var brcode: [Code]
        var money: [Amount]
    }

    static let v: Vectors = {
        let data = try! Data(contentsOf: mobile.appendingPathComponent("conformance/vectors.json"))
        return try! GoonersPayAPI.decoder.decode(Vectors.self, from: data)
    }()

    var v: Vectors { Self.v }

    func key(_ role: String) throws -> NostrKeys { try NostrKeys(secret: sha256("goonerspay-spec/test-key/" + role)) }

    func testBIP340SignaturesMatchByteForByte() throws {
        for x in v.bip340 {
            let k = try NostrKeys(secret: Data(hex: x.secret)!)
            XCTAssertEqual(x.pubkey, k.publicKeyHex)
            XCTAssertEqual(x.signature, try k.signSchnorr(Data(hex: x.message)!, aux: Data(hex: x.aux)!).hex)
        }
    }

    func testKeysNpubAndNsec() throws {
        for x in v.testKeys {
            XCTAssertEqual(x.secret, sha256("goonerspay-spec/test-key/" + x.role).hex)
            let k = try NostrKeys(secret: Data(hex: x.secret)!)
            XCTAssertEqual(x.npub, k.npub)
            XCTAssertEqual(x.nsec, k.nsec())
            XCTAssertEqual(x.secret, try NostrKeys.fromNsec(x.nsec).exportSecret().hex)
            XCTAssertEqual(x.pubkey, try Bech32.decode(hrp: "npub", x.npub).hex)
        }
        XCTAssertThrowsError(try Bech32.decode(hrp: "npub", String(v.testKeys[0].npub.dropLast()) + "q"))
    }

    func testNIP01SerializationAndSignatures() throws {
        let device = try key("merchant-device-android")
        for x in v.events {
            XCTAssertEqual(x.serialization, x.event.serialize(), x.name)
            XCTAssertEqual(x.event.id, x.event.computeID())
            XCTAssertTrue(x.event.verify())
            var unsigned = x.event
            unsigned.id = ""
            unsigned.sig = ""
            unsigned.pubkey = ""
            XCTAssertEqual(x.event.sig, try unsigned.signed(by: device, aux: Data(hex: x.aux)!).sig)
            var tampered = x.event
            tampered.content += " "
            XCTAssertFalse(tampered.verify())
        }
    }

    func testNIP98HeaderIsReproduced() throws {
        let x = v.nip98
        let rebuilt = try NIP98.event(keys: key("merchant-device-android"), method: x.method, url: x.url, body: Data(x.body.utf8),
                                      createdAt: x.event.createdAt, aux: Data(hex: x.aux)!)
        XCTAssertEqual(x.event, rebuilt)
        XCTAssertEqual(x.authorizationHeader, NIP98.header(rebuilt))
    }

    func testJWKThumbprint() {
        XCTAssertEqual(v.jwkThumbprint.thumbprint, v.jwkThumbprint.jwk.thumbprint())
    }

    func testDeviceListIsReproduced() throws {
        let ev = v.deviceList.event
        let entries = ev.tags.filter { $0[0] == "device" }.map { DeviceList.Entry(pubkeyHex: $0[1], platform: $0[2], label: $0[3]) }
        let rebuilt = try DeviceList.event(root: key("merchant-root"), merchantID: ev.tag("merchant")![1], devices: entries,
                                           createdAt: ev.createdAt, aux: Data(hex: v.deviceList.aux)!)
        XCTAssertEqual(ev, rebuilt)
    }

    func testSandboxCardFormat() throws {
        let x = v.devCard
        XCTAssertEqual(DevFormat.name, x.format)
        let card = try GoonersPayAPI.decoder.decode(DevCard.self, from: Data(x.plaintext.utf8))
        XCTAssertEqual(x.plaintext, card.json())
        let blob = try DevFormat.encrypt(key: Data(hex: x.key)!, ksn: x.ksn, card: card, nonce: Data(hex: x.nonce)!)
        XCTAssertEqual(x.ciphertextBase64, blob.base64EncodedString())
        XCTAssertEqual(card, try DevFormat.decrypt(key: Data(hex: x.key)!, ksn: x.ksn, blob: Data(base64Encoded: x.ciphertextBase64)!))
        XCTAssertThrowsError(try DevFormat.decrypt(key: Data(hex: x.key)!, ksn: x.ksn + "0", blob: blob))
    }

    func testBRCodes() throws {
        for x in v.brcode {
            let b = try BrCode.decode(x.code)
            XCTAssertEqual(x.dynamic, b.dynamic)
            XCTAssertEqual(x.amount, b.amount)
            XCTAssertEqual(x.merchantName, b.merchantName)
            if b.dynamic { XCTAssertEqual(x.url, b.url) } else { XCTAssertEqual(x.key, b.key) }
            let broken = String(x.code.dropLast()) + (x.code.last == "0" ? "1" : "0")
            XCTAssertThrowsError(try BrCode.decode(broken))
        }
    }

    func testMoney() {
        for x in v.money { XCTAssertEqual(x.display, Money(x.centavos).format()) }
    }

    /// Every signed example of the specification verifies here too.
    func testSpecExamplesVerify() throws {
        let dir = Self.mobile.deletingLastPathComponent().appendingPathComponent("nostr/examples")
        var n = 0
        func visit(_ o: Any) {
            if let d = o as? [String: Any] {
                if d["sig"] != nil, d["id"] != nil, d["kind"] != nil,
                   let data = try? JSONSerialization.data(withJSONObject: d),
                   let ev = try? GoonersPayAPI.decoder.decode(NostrEvent.self, from: data) {
                    XCTAssertTrue(ev.verify(), "\(d["id"] ?? "")")
                    n += 1
                }
                d.values.forEach(visit)
            } else if let a = o as? [Any] {
                a.forEach(visit)
            }
        }
        for f in try FileManager.default.contentsOfDirectory(atPath: dir.path) where f.hasSuffix(".json") && f != "keys.json" {
            visit(try JSONSerialization.jsonObject(with: Data(contentsOf: dir.appendingPathComponent(f))))
        }
        XCTAssertGreaterThanOrEqual(n, 15)
    }
}
